INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('field3d_faraday_glow_tokens_never_resolve_to_built_ids', 'faraday_law_induction: all 18 authored glow tokens were *_label names matching no built id — the entire narration glow track was inert', 'MAJOR', 'alex:json_author', 'The concept authored per-sentence glow tokens from a label-style vocabulary (flux_label, steady_label, push_label, …) that matches NO sceneObjects userData.id or elementType in the faraday scenario (real ids are far_coil / far_magnet / far_needle / far_push_lbl …). resolveGlowAliases (field_3d_renderer.ts) strips exactly one leading segment, so it can bridge furnace_label→s5_furnace_label but never push_label→far_push_lbl (suffix mismatch). glowTargets went non-empty each sentence → glowActive=true with no focal → every far_* object took the non-focal branch, and because the faraday applier passes brightenOnly=true, the peer-dim was also skipped: nothing brightened, nothing dimmed, and every gate stayed green (THE EYE never sends SET_GLOW; no deterministic gate resolves binding targets). Same scar family as ch6 inherited_scars "an id where every element stays at 1.0 is this bug".', 'Glow and focus targets must be REAL built ids, never invented label vocabulary. The oracle is now cheap: with the Focus Overlay host in every renderer, PM_FOCUS_HOST.resolve(id) in the sim console returns null for a token that resolves to nothing — quality_auditor Gate 3f#7 additionally requires window.PM_focusMisses to be EMPTY after a live walk. json_author spec updated with the field contract; a binding authored without a resolve() check is an authoring defect.', 'js_eval', 'For each tts_sentence glow/focus target in the concept JSON, evaluate PM_FOCUS_HOST.resolve(token) in the sim iframe on the state that carries the sentence: null for a 3D/DOM target that should exist = the scar. faraday reference: resolve("flux_label") was null pre-fix; resolve("far_coil") returns a rect post-fix.', 'FIXED', ARRAY['faraday_law_induction'], ARRAY['src/data/concepts/faraday_law_induction.json'], 'session_2026-08-19_focus_overlay', 'incident'),
('visual_validator_tts_legend_builder_expects_object_scene_composition', 'ttsBindings buildLegend reads scene_composition as {primitives:[]} but the fleet authors a flat array — the Category I vision check has never seen an authored PCPL primitive id', 'MODERATE', 'peter_parker:visual_validator', 'buildLegend() (src/lib/validators/visual/ttsBindings.ts) calls asRecord(state.scene_composition) and reads .primitives — but conceptJson.ts declares scene_composition as z.array(...) and every concept authors it as a flat array, so asRecord() returns undefined (it rejects arrays) and primitives is always []. It also reads p.properties.text/label where the fleet authors text at top level. Net: primitive_legend has only ever contained the 12 hardcoded field_3d entries, so the vision model judging I1 (glow target present) — and now I3 (focus target present) — has no legend for any authored PCPL id. The check is materially weaker than its passCriterion reads.', 'When a validator derives context from concept JSON, its shape assumptions must match the Zod schema (the schema is the contract, not a guess) — and a helper whose output is provably always-empty for the entire fleet is dead code that must fail loudly, not silently degrade a paid gate. Fix = accept the flat-array shape + top-level text/label fields; it changes what the PAID vision gate sees fleet-wide, so it ships in its own small PR after founder sign-off.', 'js_eval', 'Call extractTtsVisualBindings on any PCPL concept with authored glow bindings (e.g. scalar_vs_vector) and inspect primitive_legend: entries beyond the 12 hardcoded RENDERER_ELEMENT_LEGEND items = fixed; exactly the hardcoded 12 (or fewer) = the scar persists.', 'OPEN', ARRAY[]::text[], ARRAY[]::text[], 'session_2026-08-19_focus_overlay', 'incident'),
('authoring_reveal_primitive_id_authored_110x_read_by_nothing', 'reveal_primitive_id is authored on 110 tts_sentences and read by zero runtime consumers — decide: implement or deprecate, never silently delete', 'MODERATE', 'ambiguous', 'The field appears in proof-run design docs (.agents/proof_run/*.md) and was authored into 110 sentences across the fleet, but no player, renderer, or validator ever reads it — authors wrote 110 bindings into a table column no code consumes, and nothing failed. This is the exact failure mode the Focus Overlay wiring was built to avoid (focus was registered at the player extraction, ttsBindings keep-gate, retrofit-surgeon grep audit, and auditor gate BEFORE any binding was authored).', 'A new per-sentence authoring field ships only with its consumer and its audit registration in the same change (the reveal_primitive_id lesson, now written into the Focus Overlay spec). For the existing 110: founder decision — implement a consumer or deprecate the field and strip it on next concept touch; never a silent mass deletion.', 'manual', 'git grep "reveal_primitive_id" over src/**/*.ts must show at least one non-type consumer (player extraction, renderer, or validator) for the field to count as live; today the only hits are design docs and concept JSONs.', 'OPEN', ARRAY[]::text[], ARRAY[]::text[], 'session_2026-08-19_focus_overlay', 'directive')
